package com.learnagent.task;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.learnagent.course.CourseService;import java.util.*;import org.junit.jupiter.api.*;
class TaskServiceTest{@Test void completes_and_clears_completion_on_reopen(){StudyTaskRepository repo=mock(StudyTaskRepository.class);StudyTask task=new StudyTask(null,"Read notes",null,null,TaskPriority.MEDIUM);when(repo.save(any())).thenAnswer(i->i.getArgument(0));when(repo.findById(task.getId())).thenReturn(Optional.of(task));TaskService service=new TaskService(repo,mock(CourseService.class));service.complete(task.getId());assertThat(task.getStatus()).isEqualTo(TaskStatus.COMPLETED);assertThat(task.getCompletedAt()).isNotNull();service.update(task.getId(),new TaskDtos.Request(null,"Read notes",null,null,TaskStatus.TODO,TaskPriority.LOW));assertThat(task.getStatus()).isEqualTo(TaskStatus.TODO);assertThat(task.getCompletedAt()).isNull();}@Test void reuses_same_open_task_instead_of_creating_duplicate(){StudyTaskRepository repo=mock(StudyTaskRepository.class);StudyTask existing=new StudyTask(null,"Review Java",null,null,TaskPriority.MEDIUM);when(repo.findFirstByTitleIgnoreCaseAndCourseId("Review Java",null)).thenReturn(Optional.of(existing));TaskService service=new TaskService(repo,mock(CourseService.class));StudyTask result=service.create(new TaskDtos.Request(null,"Review Java",null,null,TaskStatus.TODO,TaskPriority.MEDIUM));assertThat(result).isSameAs(existing);verify(repo,never()).save(any());}@Test void rejects_new_task_with_past_due_date(){StudyTaskRepository repo=mock(StudyTaskRepository.class);TaskService service=new TaskService(repo,mock(CourseService.class));assertThatThrownBy(()->service.create(new TaskDtos.Request(null,"Past task",null,java.time.Instant.parse("2020-01-01T00:00:00Z"),TaskStatus.TODO,TaskPriority.MEDIUM))).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);verify(repo,never()).save(any());}}
